fix.code:
@GetMapping("/recommendations/{userId}")
public Mono<List<Product>> recommend(@PathVariable long userId) {
    return Mono.fromCallable(() -> preferenceRepository.findByUserId(userId))
        .subscribeOn(Schedulers.boundedElastic())                     // JPA chạy trên pool riêng
        .flatMap(pref -> priceClient.topProducts(pref.categories())
            .map(products -> rank(products, pref)))
        .timeout(Duration.ofSeconds(2));
}

